INSERT INTO public.process_stages (id, process_id, stage_order, name, description, scenario, execution)
VALUES
  (public.psa_mapa_uuid('stage:Relação das chaves das notas'), '550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 1, 'Relação das chaves das notas', 'Identificação das chaves de NF-e na EFD Contribuições ou nos CT-e e download manual dos XMLs, um a um, em sites gratuitos (Meu Danfe/Consulta Danfe).', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Consultas de NCM do PIS e COFINS'), 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 1, 'Consultas de NCM do PIS e COFINS', 'Consulta da tributação de PIS/COFINS de cada NCM, uma a uma no Econet, conforme período, atividade e operação, com registro na planilha MAPA — um mapa por tipo de empresa.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Consultas de NCM do ICMS'), 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 1, 'Consultas de NCM do ICMS', 'Pesquisa dos NCMs com benefício fiscal nas notas de compra do cliente e transcrição da apuração de DIFAL/ICMS para o WP Prado, com detalhamento dos valores por chave de NF-e.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Consulta CNPJ (Simples Nacional)'), 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 1, 'Consulta CNPJ (Simples Nacional)', 'Verificação, um CNPJ por vez no portal da Receita, se a empresa é optante pelo Simples Nacional, como parte do levantamento de créditos de PIS/COFINS de transportadoras.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Consulta de CNAE'), 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, 1, 'Consulta de CNAE', 'Consulta das atividades principal e secundárias dos participantes do Livro Caixa para avaliar se as despesas são da atividade rural; demorada por serem muitos participantes.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Quebra de documentos'), '94ec5922-354d-4fff-a828-a40978698866'::uuid, 1, 'Quebra de documentos', 'Conversão dos arquivos enviados pelo cliente (XML de NF-e e EFD ICMS) para Excel via TaxSheets, no formato usado para preencher os WPs de análise.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Consulta do NCM das notas fiscais do cliente para calculo de Difal (diferencial de alíquota)'), '94ec5922-354d-4fff-a828-a40978698866'::uuid, 2, 'Consulta do NCM das notas fiscais do cliente para calculo de Difal (diferencial de alíquota)', 'Consulta um a um dos NCMs das notas de compra no E-Auditoria para identificar benefício fiscal e atualização da tributação no WP, comparando depois com a apuração do cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Preenchimento do WP prado para analise do ICMS'), '94ec5922-354d-4fff-a828-a40978698866'::uuid, 3, 'Preenchimento do WP prado para analise do ICMS', 'Transcrição das informações apuradas de DIFAL e ICMS Normal para o WP Prado, com detalhamento do ICMS calculado por nota fiscal e comparação com os valores do cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Analise do ICMS das saídas do cliente'), '94ec5922-354d-4fff-a828-a40978698866'::uuid, 4, 'Analise do ICMS das saídas do cliente', 'Apuração do ICMS das operações de saída registrado no SPED Fiscal, confrontando a planilha de blocos da EFD ICMS com a análise de ICMS do cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Entrega do relatório para o cliente'), '94ec5922-354d-4fff-a828-a40978698866'::uuid, 5, 'Entrega do relatório para o cliente', 'Atualização do Diagnóstico Tributário de ICMS em PowerPoint a partir dos WPs (DIFAL e ICMS saídas) e apresentação do resumo da apuração ao cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Coleta de documentos'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 1, 'Coleta de documentos', 'Contato inicial com o cliente por e-mail para coletar os documentos do levantamento: XMLs de NF-e/CT-e, balancete, EFD Contribuições, EFD ICMS/IPI, razão contábil e ECD.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Quebra de Arquivos'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 2, 'Quebra de Arquivos', 'Conversão dos documentos recebidos (XML, TXT e PDF) para xlsx via TaxSheets e Able2Extract, preparando-os para preencher o WP e realizar comparações.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Apuração Cliente'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 3, 'Apuração Cliente', 'Conferência da apuração do cliente contra a EFD Contribuições fornecida e verificação de completude da EFD comparando com as planilhas de NF-e e EFD ICMS.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Apuração Prado'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 4, 'Apuração Prado', 'Verificação dos CSTs de PIS/COFINS com base no MAPA, balancete, razão contábil, ECD e na essencialidade do produto, ajustando a EFD para maior conformidade; NCMs consultados um a um no Econet.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Apuração de tributações Deb/Cred'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 5, 'Apuração de tributações Deb/Cred', 'Ajustes finais de ICMS para registros com tributação de PIS e para compras de fornecedores do Simples Nacional, com verificação de enquadramento no portal da Receita.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:EFD Contribuições - Parte 1'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 6, 'EFD Contribuições - Parte 1', 'Ajustes na EFD em Excel conforme a análise da Prado no WP e conversão para TXT para validação dos arquivos.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:EFD Contribuições - Parte 2'), '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, 7, 'EFD Contribuições - Parte 2', 'Abatimento dos créditos contra os débitos, carga e controle dos saldos nos registros 1100/1500 e transmissão das EFD retificadoras no PVA.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Composição dos saldos passíveis de ressarcimento'), '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 1, 'Composição dos saldos passíveis de ressarcimento', 'Quebra das EFD Contribuições retificadas para Excel via TaxSheets e levantamento dos saldos passíveis de ressarcimento constantes nos registros 1100/1500.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Controle dos saldos solicitados o ressarcimento'), '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 2, 'Controle dos saldos solicitados o ressarcimento', 'Elaboração da planilha de controle dos créditos por cliente, acompanhando o consumo via compensações até o crédito ser consumido ou analisado pela Receita Federal.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Pedido de Ressarcimento ou Restituição (PER)'), '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 3, 'Pedido de Ressarcimento ou Restituição (PER)', 'Acesso ao PERDCOMP Web no e-Cac com certificado digital ou procuração do cliente e transmissão dos pedidos de ressarcimento/restituição com base nos saldos levantados.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Fazer upload da planilha no pasta do cliente'), '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 4, 'Fazer upload da planilha no pasta do cliente', 'Salvamento da planilha de controle concluída na pasta do cliente no SharePoint; para cada cliente é criada e arquivada uma planilha de controle de créditos.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Quebra dos Documentos SPEDs'), 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, 1, 'Quebra dos Documentos SPEDs', 'Quebra das obrigações acessórias (EFD Contribuições, EFD ICMS/IPI, ECD, ECF e CT-e) em planilhas Excel via TaxSheets, para uso nos levantamentos e revisões contábeis.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Cabeçalho WP'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 1, 'Cabeçalho WP', 'Arquivo modelo de cabeçalho usado como base para os demais WPs, padronizando a apresentação dos papéis de trabalho entre as equipes.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Exportação da Cópia de Segurança IRPF e Carga no WP DIRPF'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 2, 'Exportação da Cópia de Segurança IRPF e Carga no WP DIRPF', 'Exportação da cópia de segurança no programa IRPF e colagem do texto integral, via Bloco de Notas, na coluna D2 da planilha modelo de DIRPF para permitir o confronto com o LCDPR.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Papel Padrao PIS COFINS_VF'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 3, 'Papel Padrao PIS COFINS_VF', 'Template padrão do WP de PIS/COFINS que recebe os documentos do cliente e orienta a padronização da verificação de PIS/COFINS.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Papel Padrão WP - IRPJ/CSLL'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 4, 'Papel Padrão WP - IRPJ/CSLL', 'Carga dos dados coletados (relatório de dívida, contrato de exploração rural, LCDPR) no WP Prado, que gera o Resumo LCDPR e a DRE projetada automaticamente.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:WP Calcenter - Levantamento_ME'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 5, 'WP Calcenter - Levantamento_ME', 'WP usado para o levantamento de crédito do valor a ressarcir das rubricas referentes a atestados de até 15 dias.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Apuração do LCDPR'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 6, 'Apuração do LCDPR', 'Apuração do LCDPR no WP a partir dos documentos do cliente (relatório de dívida, contrato de exploração rural, LCDPR), base para o planejamento tributário.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:WP DIFAL'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 7, 'WP DIFAL', 'Apuração do diferencial de alíquota sobre NF-e de uso/consumo e ativo imobilizado a partir das notas fiscais e da EFD ICMS/IPI, compilando as informações do cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:WP_ICMS_SAIDAS'), 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 8, 'WP_ICMS_SAIDAS', 'WP onde são analisadas as alíquotas de ICMS das operações de saída do cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Identificação dos serviços contratados por cliente'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 1, 'Identificação dos serviços contratados por cliente', 'Identificação, no início de cada período, dos serviços contratados por cliente fixo; informação dispersa em contratos PDF, e-mails e memória, sem cadastro estruturado cliente × serviços.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Definição dos prazos de entrega por serviço'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 2, 'Definição dos prazos de entrega por serviço', 'Definição do prazo de entrega de cada serviço (mensal/trimestral/anual); cada consultor controla individualmente em planilhas, Outlook, post-its ou memória, sem calendário centralizado da equipe.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Verificação da disponibilidade de documentos necessários'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 3, 'Verificação da disponibilidade de documentos necessários', 'Verificação manual na pasta do SharePoint se todos os documentos necessários já foram recebidos antes de iniciar o trabalho; sem checklist automático por serviço.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Distribuição e atribuição formal das tarefas'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 4, 'Distribuição e atribuição formal das tarefas', 'Definição informal (verbal ou mensagem) de quem faz qual trabalho para qual cliente; sem registro formal de tarefa/responsável/prazo nem visão de carga da equipe.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Execução do trabalho técnico'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 5, 'Execução do trabalho técnico', 'Execução do trabalho técnico contratado (análise fiscal, revisão contábil, apuração de tributos), variando de 2h a 40h conforme o serviço; o foco do processo 2.3 é o controle, não a execução.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Registro do status de andamento'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 6, 'Registro do status de andamento', 'Atualização do status do trabalho durante a execução; hoje não há sistema de registro, o status fica na cabeça do consultor e é descoberto por pergunta verbal.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Revisão técnica e controle de qualidade'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 7, 'Revisão técnica e controle de qualidade', 'Revisão informal dos trabalhos críticos por outro consultor ou pelo gerente antes da entrega; sem critério claro de quando revisar, sem registro de quem revisou e sem métrica de erros.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Entrega ao cliente e registro de conclusão'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 8, 'Entrega ao cliente e registro de conclusão', 'Envio do trabalho finalizado ao cliente por e-mail (maioria) ou portal, sem template padrão de e-mail nem registro formal de conclusão além do e-mail enviado.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Medição de tempo gasto e controle de produtividade'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 9, 'Medição de tempo gasto e controle de produtividade', 'Registro do tempo gasto por trabalho para precificação, planejamento e avaliação de produtividade; hoje não existe timesheet nem controle de horas por trabalho/cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Acompanhamento de prazos e alertas de vencimento'), '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 10, 'Acompanhamento de prazos e alertas de vencimento', 'Acompanhamento dos prazos de entrega; sem alertas automáticos, cada consultor controla individualmente e a cobrança é manual quando o atraso é percebido — comum descobrir prazo vencido quando o cliente cobra.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Receber Documentos e Converter PDF'), 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 1, 'Receber Documentos e Converter PDF', 'Recebimento dos documentos do cliente (LCDPR, IRPF, relatório de dívidas, contrato de exploração rural, balancete, contratos sociais), quebra do PDF do IRPF para Excel via Able2Extract e tratamento dos dados para importação no WP.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Consulta do CNAE e Apuração das Despesas/Receitas'), 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 2, 'Consulta do CNAE e Apuração das Despesas/Receitas', 'Exportação dos CNAEs únicos para outra planilha e consulta um a um para identificar e classificar os valores de entrada e saída (despesas/receitas) no WP.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Geração do Resumo LCDPR, Projeção da DRE e análise dos Cenários'), 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 3, 'Geração do Resumo LCDPR, Projeção da DRE e análise dos Cenários', 'O WP gera automaticamente o Resumo LCDPR e a DRE projetada via fórmulas pré-configuradas; o responsável analisa as projeções, elabora os cenários e consolida tudo na planilha de resumo.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Análise do Planejamento Tributário Realizado e Elaboração da Apresentação'), 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 4, 'Análise do Planejamento Tributário Realizado e Elaboração da Apresentação', 'Elaboração do material de apresentação do planejamento tributário em PowerPoint a partir do WP Prado consolidado (cenários, projeções e resumos) e apresentação ao cliente.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Recebimento da demanda de novo cliente'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 1, 'Recebimento da demanda de novo cliente', 'Comunicação da entrada de novo cliente pelo comercial/liderança via e-mail ou verbalmente e criação da pasta do cliente no SharePoint; sem formulário padrão de handover comercial → operacional.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Definição dos documentos necessários'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 2, 'Definição dos documentos necessários', 'Definição da lista de documentos a solicitar conforme o tipo de cliente e os serviços contratados; sem checklist padrão, cada analista define por experiência própria.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Preparação e envio da solicitação ao cliente'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 3, 'Preparação e envio da solicitação ao cliente', 'Montagem da lista de documentos e envio da solicitação via DocBox (20-30% dos casos) ou e-mail sem template (70-80%); cerca de 1 hora por cliente para preparar e enviar.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Registro do pedido em planilha de controle'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 4, 'Registro do pedido em planilha de controle', 'Registro do pedido em planilha manual (cliente, data, canal, documentos solicitados, status); cada analista mantém a própria planilha, sem visão consolidada da equipe.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Acompanhamento diário do status de envio'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 5, 'Acompanhamento diário do status de envio', 'Verificação manual 1x ao dia se o cliente enviou documentos, no DocBox ou na caixa de entrada, com atualização manual da planilha; 10-20 minutos por dia.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Cobrança manual ao cliente em caso de atraso'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 6, 'Cobrança manual ao cliente em caso de atraso', 'Cobrança manual via e-mail em texto livre, ligação ou DocBox quando o cliente não envia no prazo; sem alerta automático, depende da memória do analista.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Recebimento e salvamento dos documentos no SharePoint'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 7, 'Recebimento e salvamento dos documentos no SharePoint', 'Download dos documentos recebidos (anexos de e-mail, DocBox, WeTransfer ou Google Drive) e salvamento na pasta do cliente no SharePoint; estrutura de pastas varia por analista.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Validação da documentação pelo analista'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 8, 'Validação da documentação pelo analista', 'Conferência visual documento a documento se tudo foi recebido e está correto/completo; se falta algo, nova solicitação de complemento e retorno ao acompanhamento.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Conclusão do onboarding e início dos trabalhos'), 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, 9, 'Conclusão do onboarding e início dos trabalhos', 'Atualização do status na planilha para Documentação OK e início do trabalho técnico; sem comunicação formal de onboarding concluído nem marco registrado em sistema.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Entrada do projeto e cadastro inicial'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 1, 'Entrada do projeto e cadastro inicial', 'Recebimento da demanda (solicitação de projeto ou notificação/autuação RFB urgente) via e-mail, telefone ou portal; registro apenas mental ou em e-mail salvo, sem sistema centralizado.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Solicitação de documentos ao cliente'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 2, 'Solicitação de documentos ao cliente', 'Solicitação de documentos via e-mail sem template e acompanhamento manual do recebimento (planilha pessoal, marcação de e-mails ou memória); 30-60 min por projeto mais 10-20 min/dia.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Atribuição de responsáveis e priorização'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 3, 'Atribuição de responsáveis e priorização', 'Distribuição dos projetos entre os consultores conforme especialidade e carga percebida, com prioridades decididas de cabeça (prazo, valor, urgência RFB); atribuição verbal ou via WhatsApp, sem registro formal.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Acompanhamento de status e alertas de prazo'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 4, 'Acompanhamento de status e alertas de prazo', 'Acompanhamento do andamento perguntando individualmente a cada consultor; sem registro de status nem alertas automáticos, incêndios descobertos quando o prazo já passou ou o cliente reclama.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Registro de horas trabalhadas (timesheet)'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 5, 'Registro de horas trabalhadas (timesheet)', 'Registro do tempo dedicado a cada projeto para medir rentabilidade, precificar e planejar capacidade; hoje não existe timesheet nem controle de horas por projeto.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Revisão técnica e gestão de bloqueios'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 6, 'Revisão técnica e gestão de bloqueios', 'Revisão dos trabalhos críticos pelos sêniores antes da entrega; defesas RFB exigem sênior e, quando ele está ocupado, os júniores ficam bloqueados aguardando aprovação (~60h/mês de ociosidade).', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Entrega ao cliente e encerramento'), '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 7, 'Entrega ao cliente e encerramento', 'Entrega final com laudo técnico, planilhas analíticas e PER/DCOMP quando aplicável, por e-mail ou Drive, mais suporte pós-entrega; sem template padrão nem registro formal de conclusão.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Atribuição Informal e Definição de Prioridades'), 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid, 1, 'Atribuição Informal e Definição de Prioridades', 'Recebimento da demanda pelo coordenador e alocação informal aos consultores (verbal ou WhatsApp) conforme especialidade e carga percebida; tarefa criada no Planner com status, prioridade e datas.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Monitoramento Reativo'), 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid, 2, 'Monitoramento Reativo', 'Acompanhamento reativo da execução: status informal na cabeça do consultor, produtividade não medida por horas e revisões concentradas nos sêniores como ponto de bloqueio dos júniores.', 'AS-IS', 'manual'),
  (public.psa_mapa_uuid('stage:Quebra de Balancete'), '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 1, 'Quebra de Balancete', 'Conversão do balancete (PDF) para Excel (.xlsx) via Able2Extract, base para as revisões de IRPJ/CSLL e PIS/COFINS.', 'AS-IS', 'semi_automatica'),
  (public.psa_mapa_uuid('stage:Consolidação da Revisão de Tributos e Parecer'), 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 1, 'Consolidação da Revisão de Tributos e Parecer', 'Consolidação das revisões de LCDPR, IRPF, IRPJ/CSLL e PIS/COFINS: confronto das apurações do cliente com as da Prado e emissão do parecer com recomendações.', 'AS-IS', 'manual')
