INSERT INTO public.gargalos (id, nome, cluster_id, descricao, origem, melhoria_id)
VALUES
  (public.psa_mapa_uuid('gargalo:Consulta manual um a um'), 'Consulta manual um a um', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Consultas feitas individualmente em sites e portais que não aceitam lote: download de XML por chave de acesso, tributação por NCM, enquadramento de CNPJ no Simples Nacional e CNAE. Com volumes de centenas de itens por mês, a equipe gasta dias em consultas repetitivas. Origem detalhada original: Ferramentas e portais sem suporte a consulta em lote.', 'Sistema', NULL),
  (public.psa_mapa_uuid('gargalo:Conversão/quebra manual de arquivos'), 'Conversão/quebra manual de arquivos', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Antes de qualquer análise é preciso transformar XML, TXT (SPED) e PDF em Excel via TaxSheets e Able2Extract. É uma etapa preparatória repetida em quase todo serviço, sensível à quantidade de arquivos e aos formatos variáveis de PDF. Origem detalhada original: Formatos de origem incompatíveis com a análise em Excel.', 'Processo', NULL),
  (public.psa_mapa_uuid('gargalo:Transcrição/preenchimento manual de dados'), 'Transcrição/preenchimento manual de dados', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Dados copiados e digitados manualmente entre documentos e WPs: tributação consultada lançada no WP, cópia de segurança do IRPF colada via Bloco de Notas na planilha DIRPF, listas de documentos digitadas em e-mails. Processo lento e com alto risco de erro de digitação. Origem detalhada original: Falta de integração entre sistemas e planilhas.', 'Sistema', NULL),
  (public.psa_mapa_uuid('gargalo:Dependência externa'), 'Dependência externa', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'O início e o andamento dos trabalhos dependem do envio de documentos e respostas do cliente, com tempo de resposta variável e fora do controle da equipe. Trabalhos ficam parados aguardando complemento de documentação. Origem detalhada original: Fator externo (cliente e terceiros).', 'Externo', NULL),
  (public.psa_mapa_uuid('gargalo:Acompanhamento manual de recebimentos'), 'Acompanhamento manual de recebimentos', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Verificação manual diária da caixa de entrada e do DocBox para saber se o cliente enviou os documentos, com atualização manual de planilha de controle e cobrança sem alerta automático. Consome 10-20 minutos por dia por analista e falha quando há sobrecarga. Origem detalhada original: Ausência de notificação e checklist automáticos de recebimento.', 'Processo', NULL),
  (public.psa_mapa_uuid('gargalo:Falta de padronização'), 'Falta de padronização', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Cada analista redige seus e-mails, define sua lista de documentos, organiza pastas e formata WPs e laudos do seu jeito. Sem templates oficiais, há risco de esquecer documentos, qualidade desigual nas entregas e dificuldade de revisão. Origem detalhada original: Ausência de templates e procedimentos padrão.', 'Processo', NULL),
  (public.psa_mapa_uuid('gargalo:Limitação de infraestrutura'), 'Limitação de infraestrutura', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'O TaxSheets roda em um único servidor acessado via AnyDesk, criando fila e fricção no acesso. A quantidade e o tamanho dos arquivos processados (SPEDs de 50-500MB) limitam a velocidade das quebras. Origem detalhada original: Infraestrutura local insuficiente para o volume de arquivos.', 'Sistema', NULL),
  (public.psa_mapa_uuid('gargalo:Controle descentralizado'), 'Controle descentralizado', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Controles espalhados em planilhas individuais de cada analista, e-mails marcados e memória: solicitações de documentos, saldos PERDCOMP por cliente, um MAPA por tipo de empresa. Não existe visão consolidada da equipe e o líder só descobre o quadro perguntando um a um. Origem detalhada original: Ausência de sistema centralizado de controle.', 'Sistema', NULL),
  (public.psa_mapa_uuid('gargalo:Dependência de pessoa-chave'), 'Dependência de pessoa-chave', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Informações críticas ficam na cabeça de pessoas específicas: o escopo de cada cliente, a distribuição de projetos, os saldos em planilhas locais. Defesas RFB exigem sênior e júniores ficam bloqueados aguardando aprovação (estimativa de 60h/mês de ociosidade). Quando alguém sai, o conhecimento se perde. Origem detalhada original: Conhecimento não documentado e revisão concentrada nos sêniores.', 'Pessoas', NULL),
  (public.psa_mapa_uuid('gargalo:Retrabalho'), 'Retrabalho', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Trabalhos refeitos ou corrigidos: documento faltante descoberto só na hora de usar, EFDs que precisam de novos ajustes e retificações, ajustes pós-revisão. O ciclo solicitar-conferir-corrigir se repete por falta de validação antecipada. Origem detalhada original: Falta de validação antecipada e de padronização.', 'Processo', NULL),
  (public.psa_mapa_uuid('gargalo:Falta de registro formal'), 'Falta de registro formal', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Atribuições, status, revisões e entregas acontecem verbalmente ou por WhatsApp, sem registro estruturado. Não há comprovação formal de conclusão e entrega além do e-mail enviado, nem histórico de quem revisou o quê. Origem detalhada original: Processos informais sem sistema de registro.', 'Processo', NULL),
  (public.psa_mapa_uuid('gargalo:Falta de métricas de produtividade e custo'), 'Falta de métricas de produtividade e custo', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Não existe timesheet nem registro de horas por trabalho/projeto. É impossível saber se um projeto levou 20h ou 80h, medir rentabilidade, calcular o custo real de cada serviço ou avaliar a eficiência da equipe; a precificação é feita no achômetro. Origem detalhada original: Ausência de medição de tempo e custo.', 'Processo', NULL),
  (public.psa_mapa_uuid('gargalo:Gestão reativa de prazos'), 'Gestão reativa de prazos', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Sem calendário centralizado nem alertas automáticos, prazos são descobertos vencidos quando o cliente reclama ou a RFB notifica. O resultado são os incêndios mensais de fim de mês, trabalho além do horário e risco de multas para o cliente. Origem detalhada original: Ausência de sistema de alertas e calendário centralizado.', 'Sistema', NULL)
