  ('492df2ea-51f3-47cf-b602-3af69e1bd1b3'::uuid, 'Dashboard analítico e operacional para controle dos saldos de PIS/COFINS/IPI e pedidos PERDCOMP — substitui planilha de controle por cliente.', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'Melhorias', 'Tax'),
