  ('bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'Coordenação da revisão de tributos dos clientes fixos: consolida as revisões de LCDPR, IRPF, IRPJ/CSLL e PIS/COFINS, confronta as apurações do cliente com as da Prado e emite o parecer.', 'Fixos', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'd1a9fabd-8262-429e-8501-7a08a6d43ad8'::uuid, 'mapping', 'medium', 'Mensal', 'Alta', 'Não avaliado', 'Pareceres consolidados das revisões entregues ao cliente'),
  ('d3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, 'Padronização dos papéis de trabalho contábeis e fiscais: identificação dos papéis produzidos e consolidação de templates padrão (cabeçalho WP, PIS/COFINS, DIRPF, DIFAL, ICMS saídas, IRPJ/CSLL).', 'Fixos/Previdenciário', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, 'd1a9fabd-8262-429e-8501-7a08a6d43ad8'::uuid, 'mapping', 'high', 'Mensal', 'Média', 'Não avaliado', 'Templates padrão de WP consolidados e em uso pela equipe'),
  ('48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'Controle dos serviços contratados e prazos de entrega dos clientes fixos, hoje disperso em contratos, planilhas individuais e memória, sem visão consolidada, registro de status ou alertas.', 'Fixos/Previdenciário', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, '1de4789f-50ce-40bd-945a-2ae01eba5b21'::uuid, 'mapping', 'high', 'Diária', 'Média', 'Não avaliado', 'Controle consolidado de contratos, prazos e status das entregas'),
  ('c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'Planejamento tributário de produtores rurais: recebimento e conversão de documentos, classificação de despesas/receitas por CNAE, geração do Resumo LCDPR e DRE projetada, cenários e apresentação.', 'Fiscal', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, NULL, 'mapping', 'medium', 'Diária', 'Alta', 'Não avaliado', 'Apresentação do Planejamento Tributário com os cenários para o cliente'),
