  ('3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'Controle do ciclo de vida dos projetos tributários: entrada e cadastro da demanda, solicitação de documentos, atribuição de responsáveis, acompanhamento de status e prazos, revisão técnica e entrega.', 'Consultoria', 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid, '1de4789f-50ce-40bd-945a-2ae01eba5b21'::uuid, 'mapping', 'high', 'Diária', 'Média', 'Não avaliado', 'Projeto entregue ao cliente (laudo técnico, planilhas e PER/DCOMP quando aplicável)'),
