)
UPDATE public.processes p SET
  description = src.description,
  area = src.area,
  cluster_id = src.cluster_id,
  project_id = src.project_id,
  stage = src.stage,
  priority = src.priority,
  frequency = src.frequency,
  complexity_level = src.complexity_level,
  evaluation_status = src.evaluation_status,
  deliverable = src.deliverable,
  updated_at = NOW()
FROM src
WHERE p.id = src.id;

-- Etapas AS-IS substituídas: JSON inline fica vazio; MAPA lê documentos/sistemas por pontes.
ON CONFLICT (id, scenario) DO UPDATE SET
  process_id = EXCLUDED.process_id,
  stage_order = EXCLUDED.stage_order,
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  execution = EXCLUDED.execution,
  updated_at = NOW();

-- Catálogo de documentos do cluster PSA.
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome,
  cluster_id = EXCLUDED.cluster_id,
  categoria = EXCLUDED.categoria,
  tipo = EXCLUDED.tipo,
  formato = EXCLUDED.formato,
  origem = EXCLUDED.origem,
  estruturado = EXCLUDED.estruturado,
  estrutura_entrada = EXCLUDED.estrutura_entrada,
  updated_at = NOW();

-- Catálogo de sistemas do cluster PSA.
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome,
  cluster_id = EXCLUDED.cluster_id,
  descricao = EXCLUDED.descricao,
  origem = EXCLUDED.origem,
  tipo = EXCLUDED.tipo,
  tipo_custo = EXCLUDED.tipo_custo,
  obs_licenca = EXCLUDED.obs_licenca,
  obs_variavel = EXCLUDED.obs_variavel,
  obs_custo_por_operacao = EXCLUDED.obs_custo_por_operacao,
  updated_at = NOW();

-- Gargalos qualitativos do cluster PSA. Campos quantitativos ficam NULL nesta rodada.
ON CONFLICT (id) DO UPDATE SET
  nome = EXCLUDED.nome,
  cluster_id = EXCLUDED.cluster_id,
  descricao = EXCLUDED.descricao,
  origem = EXCLUDED.origem,
  melhoria_id = EXCLUDED.melhoria_id,
  updated_at = NOW();

-- Melhorias: process_id é âncora obrigatória de compatibilidade; relação canônica é melhoria_processos.
ON CONFLICT (id) DO UPDATE SET
  improvement_description = EXCLUDED.improvement_description,
  cluster_id = EXCLUDED.cluster_id,
  process_id = EXCLUDED.process_id,
  project_id = EXCLUDED.project_id,
  improvement_status = EXCLUDED.improvement_status,
  evaluation_status = EXCLUDED.evaluation_status,
  updated_at = NOW();

-- Pontes etapa ↔ documentos.
ON CONFLICT ON CONSTRAINT etapa_documentos_uniq DO UPDATE SET volume = EXCLUDED.volume;

-- Pontes etapa ↔ sistemas.
ON CONFLICT ON CONSTRAINT etapa_sistemas_uniq DO UPDATE SET rateio = EXCLUDED.rateio;

-- Pontes etapa ↔ responsáveis globais.
ON CONFLICT ON CONSTRAINT etapa_responsaveis_uniq DO UPDATE SET horas = EXCLUDED.horas;

-- Pontes gargalo ↔ etapa-origem.
ON CONFLICT ON CONSTRAINT gargalo_etapas_uniq DO NOTHING;

-- Pontes gargalo ↔ melhoria.
ON CONFLICT ON CONSTRAINT gargalo_melhorias_uniq DO NOTHING;

-- Pontes melhoria ↔ processos legado.
ON CONFLICT (melhoria_id, processo_id) DO NOTHING;

DO $$
DECLARE
  v_count integer;
BEGIN
  SELECT count(*) INTO v_count FROM public.projects WHERE id = ANY(ARRAY['d1a9fabd-8262-429e-8501-7a08a6d43ad8'::uuid, '4cb03075-d8a7-4062-9d51-a9c64dc47523'::uuid, 'cc5ef9ae-0425-4b4b-8035-c10af1d6bef6'::uuid, '1de4789f-50ce-40bd-945a-2ae01eba5b21'::uuid, '267dd955-3be2-4b51-ab14-c8237ecbaa3a'::uuid, '280035db-24c6-4c1c-9374-474acfb5663d'::uuid, '492df2ea-51f3-47cf-b602-3af69e1bd1b3'::uuid, '6e237fa4-4507-4137-84f6-0d11db63d46f'::uuid, '20c83382-dbdf-49ef-a915-ca97dcd53a64'::uuid, '3489ea0a-6d60-41c3-9784-591aa0c65572'::uuid]::uuid[]) AND cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
  IF v_count <> 10 THEN
    RAISE EXCEPTION 'Projetos PSA: esperado 10, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.processes WHERE id = ANY(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, '94ec5922-354d-4fff-a828-a40978698866'::uuid, '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid]::uuid[]) AND cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
  IF v_count <> 17 THEN
    RAISE EXCEPTION 'Processos PSA: esperado 17, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.process_stages WHERE process_id = ANY(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, '94ec5922-354d-4fff-a828-a40978698866'::uuid, '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid]::uuid[]) AND scenario = 'AS-IS';
  IF v_count <> 64 THEN
    RAISE EXCEPTION 'Etapas PSA: esperado 64, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.documentos_processo WHERE cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
  IF v_count <> 78 THEN
    RAISE EXCEPTION 'Documentos PSA: esperado 78, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.sistemas_processo WHERE cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
  IF v_count <> 22 THEN
    RAISE EXCEPTION 'Sistemas PSA: esperado 22, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.gargalos WHERE cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
  IF v_count <> 13 THEN
    RAISE EXCEPTION 'Gargalos PSA: esperado 13, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.process_improvements WHERE cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
  IF v_count <> 21 THEN
    RAISE EXCEPTION 'Melhorias PSA: esperado 21, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.etapa_documentos WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, '94ec5922-354d-4fff-a828-a40978698866'::uuid, '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid]::uuid[]));
  IF v_count <> 152 THEN
    RAISE EXCEPTION 'etapa_documentos PSA: esperado 152, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.etapa_sistemas WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, '94ec5922-354d-4fff-a828-a40978698866'::uuid, '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid]::uuid[]));
  IF v_count <> 90 THEN
    RAISE EXCEPTION 'etapa_sistemas PSA: esperado 90, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.etapa_responsaveis WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, '94ec5922-354d-4fff-a828-a40978698866'::uuid, '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid]::uuid[]));
  IF v_count <> 77 THEN
    RAISE EXCEPTION 'etapa_responsaveis PSA: esperado 77, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.gargalo_etapas ge JOIN public.process_stages ps ON ps.id = ge.etapa_id AND ps.scenario = ge.scenario WHERE ps.process_id = ANY(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015'::uuid, 'ca800dfa-c14e-4b4e-89d9-10d6dd1da235'::uuid, 'ec58feca-8367-409f-8cd6-b880644896b6'::uuid, 'ad8a6b69-2579-4a16-b708-6319555a87f9'::uuid, 'fc0233c3-08b5-4428-be6f-332634cc9c24'::uuid, '94ec5922-354d-4fff-a828-a40978698866'::uuid, '4d6476ae-93fe-46ec-843a-02824e6d4800'::uuid, '16a7c7f1-2d7a-4097-a05a-76d0d28183f2'::uuid, 'fd3d188d-1582-4d1d-96a2-7a73fd04de3d'::uuid, '5c2c1c02-e51e-4790-b251-15f2306ca545'::uuid, 'bda94caf-9811-4177-b1c0-088b253c0243'::uuid, 'd3c7e6f6-bc08-40b0-9d4a-e31e47a0c821'::uuid, '48d2e792-3fd2-41c1-a357-582a553d38d9'::uuid, 'c7db1b56-22cc-4c8d-b36a-b280f8944172'::uuid, 'bfd4a06a-de80-4fbe-9955-a877a551a3dc'::uuid, '3d896cea-f554-42f4-a7b9-8ec61195c71d'::uuid, 'c1012dd1-2296-4464-bcec-be7e9bfbed77'::uuid]::uuid[]);
  IF v_count <> 68 THEN
    RAISE EXCEPTION 'gargalo_etapas PSA: esperado 68, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.gargalo_melhorias WHERE gargalo_id IN (SELECT id FROM public.gargalos WHERE cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid);
  IF v_count <> 38 THEN
    RAISE EXCEPTION 'gargalo_melhorias PSA: esperado 38, encontrado %', v_count;
  END IF;
  SELECT count(*) INTO v_count FROM public.melhoria_processos WHERE melhoria_id IN (SELECT id FROM public.process_improvements WHERE cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid);
  IF v_count <> 29 THEN
    RAISE EXCEPTION 'melhoria_processos PSA: esperado 29, encontrado %', v_count;
  END IF;
  IF EXISTS (SELECT 1 FROM public.processes WHERE code = 'PROC-GERAL-001' AND cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid) THEN
    RAISE EXCEPTION 'PROC-GERAL-001 não pode estar no cluster PSA';
  END IF;
END $$;

COMMIT;
